import {createClient} from 'https://esm.sh/@supabase/supabase-js@2.49.8';
// JOKER STORE production candidate V3: uses the EXISTING Supabase project.
// Never paste a service_role key in config.js. SQL migration + RLS must be reviewed first.
const cfg=window.JOKER_CONFIG||{};
const ready=Boolean(cfg.supabaseUrl?.startsWith('https://')&&cfg.supabasePublishableKey&&!cfg.supabasePublishableKey.startsWith('PASTE_'));
const db=ready?createClient(cfg.supabaseUrl,cfg.supabasePublishableKey,{auth:{persistSession:true,autoRefreshToken:true}}):null;
const $=id=>document.getElementById(id);
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=x=>Number(x||0).toFixed(2)+' د.ل';
const pnum=x=>Number.isFinite(Number(x))?Number(x):0;
const randomId=()=>crypto?.randomUUID?.()||'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g,c=>{let r=Math.floor(Math.random()*16);return (c==='x'?r:(r&3|8)).toString(16)});
const dateText=x=>new Date(x).toLocaleString('ar-LY',{dateStyle:'medium',timeStyle:'short'});
const now=()=>Date.now();
const currentOffer=p=>store.offers.find(o=>String(o.product_id)===String(p.id)&&new Date(o.start_at).getTime()<=now()&&new Date(o.end_at).getTime()>now()&&Number(o.offer_price)>0&&Number(o.offer_price)<Number(p.price));
const salePrice=p=>pnum(currentOffer(p)?.offer_price??p.price);
const pricing=p=>{const special=currentOffer(p),price=special?pnum(special.offer_price):pnum(p.price),old=special?pnum(p.price):pnum(p.old_price);return {price,old:old>price?old:0,discount:old>price?Math.round(100*(old-price)/old):0,offer:special}};
const timeLeft=x=>{let d=Math.max(0,Date.parse(x)-now()),days=Math.floor(d/86400000),h=Math.floor(d%86400000/3600000),m=Math.floor(d%3600000/60000),s=Math.floor(d%60000/1000);return (days?days+' يوم و ':'')+[h,m,s].map(v=>String(v).padStart(2,'0')).join(':')};
const localDate=x=>{let d=new Date(x),delta=d.getTimezoneOffset()*60000;return new Date(d.getTime()-delta).toISOString().slice(0,16)};
const safeCart=()=>{try{const x=JSON.parse(localStorage.getItem('joker_cart_v3')||'{}');return x&&typeof x==='object'&&!Array.isArray(x)?Object.fromEntries(Object.entries(x).filter(([k,v])=>k&&Number.isInteger(v)&&v>0&&v<=20)):{};}catch{return {}}};
const persistCart=()=>{try{localStorage.setItem('joker_cart_v3',JSON.stringify(store.cart))}catch{}};
const getFavs=()=>{try{return JSON.parse(localStorage.getItem('joker_favs_v3')||'[]')||[]}catch{return []}};
const store={categories:[],products:[],offers:[],orders:[],cart:safeCart(),favorites:getFavs(),cat:'all',adminTab:'overview',orderFilter:'active',actor:null,blocked:[],lastIds:null,uiBusy:false,likeVisitor:null,liked:false};
let noticeTimer=null,notifyTimer=null,tickTimer=null;
function toast(message){let el=$('toast');el.textContent=message;el.classList.add('show');clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>el.classList.remove('show'),3700)}
function status(message){const el=$('storeStatus');el.hidden=!message;el.textContent=message||''}
function modal(title,content,wide=false){$('dlgTitle').textContent=title;$('dlgContent').innerHTML=content;$('dialog').classList.toggle('wide',wide);$('shade').classList.add('show')}
function closeModal(){$('shade').classList.remove('show')}
function fail(err){toast('تعذر تنفيذ العملية: '+(err?.message||String(err)));console.error(err)}
function isOwner(){return Boolean(store.actor?.owner)}
function can(permission){return isOwner()||(store.actor?.permissions||[]).includes(permission)}
function requires(permission){if(can(permission))return true;toast('⛔ لا تملك صلاحية تنفيذ العملية');return false}
function authInfo(){return store.actor?isOwner()?'المدير العام':store.actor.name:'غير مسجل'}
async function query(table,opts={}){const {data,error}=await db.from(table).select(opts.select||'*');if(error)throw error;return data||[]}
async function loadStore(){if(!db){status('المتجر يحتاج ملف config.js الخاص بالمشروع الأصلي. لا تضع أي مفتاح سري هنا.');return}try{
  const [c,p,o]=await Promise.all([db.from('categories').select('*').order('name'),db.from('products').select('*').order('created_at',{ascending:false}),db.from('joker_offers').select('*')]);
  if(c.error)throw c.error;if(p.error)throw p.error;store.categories=c.data||[];store.products=p.data||[];
  if(o.error){store.offers=[];status('لم تُفعّل قاعدة بيانات العروض بعد. أُوقف العرض المؤقت لحين إعدادها بأمان.')}else{store.offers=o.data||[];status('')}
  renderAll();
}catch(e){status('تعذر تحميل المنتجات من قاعدة البيانات: '+e.message);fail(e)}}
function updateCounts(){ $('cartCount').textContent=Object.values(store.cart).reduce((s,v)=>s+Number(v||0),0)}
function renderCategories(){const c=[{id:'all',name:'الكل'},{id:'offer',name:'⚡ عروض الجوكر المميزة'},...store.categories,{id:'fav',name:'المفضلة'}];$('categories').innerHTML=c.map(x=>`<button class="chip ${store.cat===x.id?'active':''}" data-cat="${esc(x.id)}">${esc(x.name)}</button>`).join('');$('categories').querySelectorAll('[data-cat]').forEach(b=>b.onclick=()=>{store.cat=b.dataset.cat;renderCategories();renderProducts()})}
function productCard(p){const v=pricing(p),pic=p.image_url?`<img class="productPhoto" src="${esc(p.image_url)}" alt="${esc(p.name)}" loading="lazy" onerror="this.replaceWith(document.createTextNode('📦'))">`:'<span class="illustration">📦</span>';return `<article class="product"><div class="pic">${pic}${v.discount?`<span class="off">خصم ${v.discount}%</span>`:''}${v.offer?'<span class="dealFlag">⚡ عرض محدود</span>':''}<button aria-label="إضافة للمفضلة" class="heart" data-fav="${esc(p.id)}">${store.favorites.includes(String(p.id))?'♥':'♡'}</button></div><div class="details"><h3>${esc(p.name)}</h3><div class="mute textsm">${esc(p.description||'')}</div><div class="price"><strong>${fmt(v.price)}</strong>${v.old?`<del>${fmt(v.old)}</del>`:''}</div>${v.offer?`<div class="dealTime"><span>⏳ متبقٍ:</span><strong data-until="${esc(v.offer.end_at)}">${timeLeft(v.offer.end_at)}</strong></div>`:''}<div class="prodactions"><button class="gold" data-add="${esc(p.id)}" ${p.available===false?'disabled':''}>${p.available===false?'غير متوفر':'+ أضف للسلة'}</button><button class="outline" data-detail="${esc(p.id)}">تفاصيل</button></div></div></article>`}
function bindCards(root){root.querySelectorAll('[data-add]').forEach(b=>b.onclick=()=>addCart(b.dataset.add));root.querySelectorAll('[data-fav]').forEach(b=>b.onclick=()=>{let id=b.dataset.fav;store.favorites=store.favorites.includes(id)?store.favorites.filter(x=>x!==id):[...store.favorites,id];localStorage.setItem('joker_favs_v3',JSON.stringify(store.favorites));renderProducts();renderOffers()});root.querySelectorAll('[data-detail]').forEach(b=>b.onclick=()=>{const p=store.products.find(x=>String(x.id)===b.dataset.detail);if(!p)return;const v=pricing(p);modal(p.name,`${p.image_url?`<img src="${esc(p.image_url)}" alt="${esc(p.name)}" style="display:block;max-width:100%;max-height:260px;margin:auto;object-fit:contain;border-radius:12px">`:''}<p>${esc(p.description||'')}</p><p>القسم: ${esc(store.categories.find(c=>String(c.id)===String(p.category_id))?.name||'عام')}</p><div class="price"><strong>${fmt(v.price)}</strong>${v.old?`<del>${fmt(v.old)}</del>`:''}</div>${v.offer?`<div class="dealTime">متبقٍ: <strong data-until="${esc(v.offer.end_at)}">${timeLeft(v.offer.end_at)}</strong></div>`:''}<button class="gold" id="detailAdd" ${p.available===false?'disabled':''}>أضف للسلة</button>`);$('detailAdd').onclick=()=>{addCart(p.id);closeModal()}})}
function renderOffers(){const active=store.products.filter(p=>p.available!==false&&currentOffer(p));$('offerCards').innerHTML=active.map(productCard).join('')||'<div class="offerEmpty" style="grid-column:1/-1">لا توجد عروض فعّالة حاليًا. تابع قسم عروض الجوكر قريبًا ⚡</div>';bindCards($('offerCards'))}
function renderProducts(){const s=$('search').value.trim().toLowerCase(),sort=$('sort').value;let arr=store.products.filter(p=>p.available!==false&&(!s||p.name.toLowerCase().includes(s))&&(store.cat==='all'||store.cat==='offer'&&!!currentOffer(p)||store.cat==='fav'&&store.favorites.includes(String(p.id))||String(store.cat)===String(p.category_id)));if(sort==='low')arr.sort((a,b)=>salePrice(a)-salePrice(b));if(sort==='high')arr.sort((a,b)=>salePrice(b)-salePrice(a));if(sort==='sale')arr.sort((a,b)=>pricing(b).discount-pricing(a).discount);$('products').innerHTML=arr.map(productCard).join('')||'<p class="mute">لا توجد منتجات مطابقة.</p>';bindCards($('products'))}
function renderAll(){renderCategories();renderOffers();renderProducts();updateCounts()}
function addCart(id){const p=store.products.find(x=>String(x.id)===String(id));if(!p||p.available===false)return;store.cart[id]=Math.min(20,Number(store.cart[id]||0)+1);persistCart();updateCounts();toast('✓ أُضيف المنتج إلى السلة')}
function cartLines(){return store.products.filter(p=>store.cart[p.id]>0&&p.available!==false).map(p=>({...p,qty:store.cart[p.id],unitPrice:salePrice(p)}))}
function renderCart(){const items=cartLines(),total=items.reduce((s,p)=>s+p.unitPrice*p.qty,0);modal('🛒 سلة المشتريات',items.length?`${items.map(p=>`<div class="rows"><div><strong>${esc(p.name)}</strong><div class="mute textsm">${fmt(p.unitPrice)} × ${p.qty}</div></div><div class="steps"><button class="outline smallBtn" data-minus="${esc(p.id)}">−</button><button class="outline smallBtn" data-plus="${esc(p.id)}">+</button></div></div>`).join('')}<h3>الإجمالي: ${fmt(total)}</h3><button class="gold" id="checkout">إتمام الطلب</button>`:'<p>السلة فارغة. أضف منتجًا أولًا.</p>');$('dlgContent').querySelectorAll('[data-minus]').forEach(b=>b.onclick=()=>{let id=b.dataset.minus;store.cart[id]--;if(store.cart[id]<=0)delete store.cart[id];persistCart();updateCounts();renderCart()});$('dlgContent').querySelectorAll('[data-plus]').forEach(b=>b.onclick=()=>{let id=b.dataset.plus;store.cart[id]=Math.min(20,store.cart[id]+1);persistCart();updateCounts();renderCart()});if($('checkout'))$('checkout').onclick=()=>checkoutForm()}
function receipt(order){const w=window.open('','_blank');if(!w)return toast('اسمح بالنوافذ المنبثقة لتصدير PDF');let rows=order.items.map(p=>`<tr><td>${esc(p.name)}</td><td>${p.quantity}</td><td>${fmt(p.price)}</td><td>${fmt(p.quantity*p.price)}</td></tr>`).join('');w.document.write(`<!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><title>فاتورة ${esc(order.id)}</title><style>body{font:16px Tahoma,Arial;max-width:800px;margin:auto;padding:25px}table{width:100%;border-collapse:collapse}td,th{border:1px solid #bbb;padding:10px;text-align:right}h1{color:#a27732}</style></head><body><h1>متجر الجوكر للإلكترونيات</h1><p>رقم الطلب: ${esc(order.id)}<br>الاسم: ${esc(order.name)}<br>الهاتف: ${esc(order.phone)}<br>واتساب: ${esc(order.whatsapp)}<br>العنوان: ${esc(order.address)}</p><table><tr><th>المنتج</th><th>الكمية</th><th>السعر</th><th>الإجمالي</th></tr>${rows}</table><h2>الإجمالي: ${fmt(order.total)}</h2><p>هذه فاتورة طلب أولية، ويتم تأكيد التسليم من المتجر.</p></body></html>`);w.document.close();setTimeout(()=>{w.focus();w.print()},350)}
// WhatsApp checkout: no external subscription or WhatsApp API is used.
// The three receiver numbers are selected with equal probability for EACH saved order.
const WHATSAPP_ORDER_RECEIVERS=Object.freeze(['218915206879','218923319182','218925206879']);
function chooseOrderReceiver(){
  const count=WHATSAPP_ORDER_RECEIVERS.length;
  if(typeof crypto==='undefined'||!crypto.getRandomValues) return WHATSAPP_ORDER_RECEIVERS[Math.floor(Math.random()*count)];
  const max=0x100000000,limit=max-(max%count),buffer=new Uint32Array(1);
  do{crypto.getRandomValues(buffer)}while(buffer[0]>=limit);
  return WHATSAPP_ORDER_RECEIVERS[buffer[0]%count];
}
function normalizePhoneDigits(value){return String(value||'').replace(/[٠-٩]/g,x=>String(x.charCodeAt(0)-0x0660)).replace(/[۰-۹]/g,x=>String(x.charCodeAt(0)-0x06F0))}
function isValidCustomerPhone(value){const v=normalizePhoneDigits(value).trim();const digits=(v.match(/[0-9]/g)||[]).length;return /^\+?[0-9()\s.\-]+$/.test(v)&&digits>=8&&digits<=15}
function whatsappText(o){return [
  '🃏 طلب جديد من متجر الجوكر',
  'رقم الطلب: '+o.id,
  '👤 اسم الزبون: '+o.name,
  '📞 رقم الهاتف: '+o.phone,
  '📱 واتساب الزبون: '+o.whatsapp,
  '📍 العنوان: '+(o.address||'-'),
  '📝 ملاحظات: '+(o.notes||'-'),
  '', '🛒 تفاصيل المشتريات:',
  ...o.items.map((item,i)=>[String(i+1)+') '+item.name,'   الكمية: '+item.quantity,'   سعر القطعة: '+fmt(item.price),'   إجمالي المنتج: '+fmt(Number(item.price)*Number(item.quantity))].join('\n')),
  '', '💰 الإجمالي الكلي: '+fmt(o.total)
].join('\n')}
function confirmOrder(o){
  // The chosen WhatsApp number stays fixed for this completed order and all repeated clicks.
  const receiver=o.assignedWhatsapp||chooseOrderReceiver();
  o.assignedWhatsapp=receiver;
  const url='https://wa.me/'+receiver+'?text='+encodeURIComponent(whatsappText(o));
  modal('✅ تم تسجيل الطلب',`<div class="summary"><h3>طلبك رقم ${esc(o.id)}</h3><p>الإجمالي: <strong>${fmt(o.total)}</strong></p><p>تم تسجيل طلبك في المتجر. اضغط على زر واتساب أدناه ثم اضغط إرسال داخل واتساب لإرسال تفاصيل الطلب إلى أحد أرقام المتجر.</p></div><div class="steps"><a class="gold" id="openWhatsapp" href="${esc(url)}" target="_blank" rel="noopener noreferrer" style="display:inline-flex;align-items:center;justify-content:center;text-decoration:none;min-height:44px;padding:10px 16px">💬 إرسال تفاصيل الطلب عبر واتساب</a><button class="outline" id="printReceipt">🧾 فاتورة / PDF</button></div>`);
  $('printReceipt').onclick=()=>receipt(o);
}
function checkoutForm(){
  if(!db)return toast('الاتصال بقاعدة البيانات غير مضبوط');
  if(!cartLines().length)return toast('السلة فارغة');
  // Name and phone are mandatory; native required + explicit JavaScript validation.
  modal('تأكيد طلبك',`<form id="orderForm"><label class="field"><span>اسم الزبون (إجباري)</span><input name="name" maxlength="100" required autocomplete="name" placeholder="اكتب اسمك"></label><label class="field"><span>رقم الهاتف (إجباري)</span><input name="phone" type="tel" maxlength="25" required inputmode="tel" autocomplete="tel" placeholder="مثال: 0912345678"></label><label class="field"><span>رقم الواتساب (اختياري)</span><input name="whatsapp" type="tel" maxlength="25" inputmode="tel"></label><label class="field"><span>عنوان التوصيل</span><input name="address" maxlength="250"></label><label class="field"><span>ملاحظات الطلب</span><textarea name="notes" maxlength="500" rows="3"></textarea></label><p class="mute textsm">بعد تأكيد الطلب ستظهر رسالة واتساب جاهزة، وسترسلها بنفسك بالضغط على إرسال داخل واتساب.</p><button class="gold" type="submit">تأكيد الطلب والمتابعة إلى واتساب</button><p id="orderError" class="order-error" role="alert"></p></form>`);
  $('orderForm').onsubmit=async e=>{
    e.preventDefault();
    if(store.uiBusy)return;
    const form=e.currentTarget,btn=form.querySelector('[type=submit]');
    const f=new FormData(form),name=String(f.get('name')||'').trim(),rawPhone=String(f.get('phone')||'').trim(),rawWhatsapp=String(f.get('whatsapp')||'').trim();
    const phone=normalizePhoneDigits(rawPhone),wa=normalizePhoneDigits(rawWhatsapp||rawPhone);
    const address=String(f.get('address')||'').trim(),notes=String(f.get('notes')||'').trim();
    const err=$('orderError');
    err.textContent='';
    if(!name){err.textContent='يرجى كتابة اسم الزبون قبل إرسال الطلب.';form.querySelector('[name=name]')?.focus();return}
    if(!rawPhone){err.textContent='يرجى كتابة رقم هاتف الزبون قبل إرسال الطلب.';form.querySelector('[name=phone]')?.focus();return}
    if(!isValidCustomerPhone(phone)){err.textContent='يرجى كتابة رقم هاتف صحيح (من 8 إلى 15 رقمًا).';form.querySelector('[name=phone]')?.focus();return}
    if(rawWhatsapp&&!isValidCustomerPhone(wa)){err.textContent='رقم واتساب الزبون غير صحيح. راجعه أو اتركه فارغًا.';form.querySelector('[name=whatsapp]')?.focus();return}
    const lines=cartLines().map(p=>({product_id:String(p.id),quantity:p.qty}));
    if(!lines.length){err.textContent='السلة فارغة؛ أضف منتجًا قبل المتابعة.';return}
    store.uiBusy=true;btn.disabled=true;
    try{
      const {data,error}=await db.rpc('joker_place_order',{
        p_customer_name:name,p_customer_phone:phone,p_customer_whatsapp:wa,
        p_address:address,p_notes:notes,p_lines:lines
      });
      if(error)throw error;
      if(!data?.id||!Array.isArray(data.items))throw Error('لم يصل تأكيد حفظ الطلب');
      const order={id:String(data.id),name,phone,whatsapp:wa,address,notes,total:pnum(data.total),items:data.items,assignedWhatsapp:chooseOrderReceiver()};
      store.cart={};persistCart();updateCounts();confirmOrder(order);
    }catch(ex){
      const visible=$('orderError');if(visible)visible.textContent=ex.message||'تعذر حفظ الطلب. لا تُرسل رسالة واتساب قبل التأكد من تسجيل الطلب.';
      btn.disabled=false;
    }finally{store.uiBusy=false}
  };
}
$('close').onclick=closeModal;$('shade').onclick=e=>{if(e.target===$('shade'))closeModal()};document.onkeydown=e=>{if(e.key==='Escape')closeModal()};
$('browse').onclick=()=>$('shop').scrollIntoView({behavior:'smooth'});$('goDeals').onclick=()=>$('featuredOffers').scrollIntoView({behavior:'smooth'});
$('search').oninput=renderProducts;$('sort').onchange=renderProducts;$('cartBtn').onclick=renderCart;
let lastOfferStates='';tickTimer=setInterval(()=>{document.querySelectorAll('[data-until]').forEach(x=>x.textContent=timeLeft(x.dataset.until));const sig=store.offers.map(o=>o.id+':'+(Date.parse(o.start_at)<=now()&&Date.parse(o.end_at)>now())).join('|');if(sig!==lastOfferStates){lastOfferStates=sig;renderOffers();renderProducts()}},15000);setInterval(async()=>{if(!db||document.hidden)return;const {data,error}=await db.from('joker_offers').select('*');if(!error){store.offers=data||[];renderOffers();renderProducts()}},120000);

// Administration: real Supabase Auth accounts, NOT demo PINs.
const PERMISSIONS=[['reports.view','عرض إحصائيات المتجر'],['orders.view','مشاهدة الطلبات'],['orders.create','إضافة طلب أو بيع يدوي'],['orders.status','تغيير حالة الطلب'],['orders.archive','تسليم الطلب وأرشفته'],['orders.delete','إخفاء الطلب (حذف منطقي)'],['orders.export','تصدير الطلبات CSV'],['orders.whatsapp','نسخ الطلب عبر واتساب'],['products.view','مشاهدة المنتجات'],['products.add','إضافة منتجات'],['products.edit','تعديل بيانات المنتجات'],['products.delete','حذف المنتجات'],['products.photos','رفع صور المنتجات'],['products.prices','تعديل الأسعار والتخفيضات'],['categories.manage','إدارة الأقسام'],['offers.view','مشاهدة العروض'],['offers.manage','إدارة العروض المؤقتة'],['blocked.manage','حظر وإلغاء حظر الأرقام'],['feedback.view','قراءة اقتراحات العملاء'],['vip.view','مشاهدة أعضاء VIP وبياناتهم'],['vip.points','إدارة نقاط أعضاء VIP'],['vip.feature','اختيار عضو الجوكر المميز لهذا الشهر']];
function beep(){try{const A=window.AudioContext||window.webkitAudioContext;if(!A)return;const a=new A(),osc=a.createOscillator(),gain=a.createGain();osc.frequency.value=880;gain.gain.value=.07;osc.connect(gain);gain.connect(a.destination);osc.start();osc.stop(a.currentTime+.18);osc.onended=()=>a.close()}catch{}}
function stopNotify(){if(notifyTimer)clearInterval(notifyTimer);notifyTimer=null;store.lastIds=null;$('pending').textContent='0'}
async function checkOrders(){if(!can('orders.view')||document.hidden)return;try{const {data,error}=await db.from('orders').select('id,created_at').eq('status','new').order('created_at',{ascending:false}).limit(100);if(error)return;const list=new Set((data||[]).map(o=>String(o.id))),hasNew=store.lastIds!==null&&[...list].some(x=>!store.lastIds.has(x));store.lastIds=list;$('pending').textContent=list.size;if(hasNew){beep();toast('🔔 وصل طلب جديد إلى متجر الجوكر')}}catch{}}
function startNotify(){stopNotify();if(!can('orders.view'))return;checkOrders();notifyTimer=setInterval(checkOrders,20000)}
$('notify').onclick=()=>{beep();toast('التنبيهات تعمل عند فتح لوحة الإدارة ووجود طلب جديد')};
async function verifyActor(){if(!db)return null;const {data,error}=await db.auth.getUser();if(error||!data.user)return null;const uid=data.user.id;
  const a=await db.from('admin_users').select('user_id').eq('user_id',uid).maybeSingle();
  if(!a.error&&a.data)return {owner:true,id:uid,name:'المدير العام',email:data.user.email,permissions:PERMISSIONS.map(x=>x[0])};
  const s=await db.from('joker_staff').select('user_id,name,email,active,permissions').eq('user_id',uid).maybeSingle();
  if(s.error||!s.data||!s.data.active)return null;
  return {owner:false,id:uid,name:s.data.name,email:s.data.email,permissions:s.data.permissions||[]};
}
async function login(){if(!db)return toast('قاعدة البيانات غير متصلة');const {data}=await db.auth.getSession();if(data?.session){store.actor=await verifyActor();if(store.actor){startNotify();adminPanel();return}await db.auth.signOut()}
modal('🔐 دخول إدارة متجر الجوكر',`<form id="loginForm"><label class="field"><span>البريد الإلكتروني</span><input type="email" name="email" required autocomplete="username"></label><label class="field"><span>كلمة المرور</span><input type="password" name="password" required autocomplete="current-password"></label><button class="gold">تسجيل الدخول</button><p class="order-error" id="loginError"></p></form><p class="mute textsm">يستخدم المدير والموظفون حسابات Supabase Auth منفصلة وآمنة، دون رموز تجريبية.</p>`);$('loginForm').onsubmit=async e=>{e.preventDefault();const btn=e.target.querySelector('button');btn.disabled=true;try{const f=new FormData(e.target),{error}=await db.auth.signInWithPassword({email:String(f.get('email')),password:String(f.get('password'))});if(error)throw error;store.actor=await verifyActor();if(!store.actor){await db.auth.signOut();throw Error('الحساب غير مخوّل أو معطّل في المتجر')}startNotify();adminPanel()}catch(x){$('loginError').textContent=x.message||'تعذر تسجيل الدخول';btn.disabled=false}}}
