function adminPanel(){if(!store.actor)return login();const tabs=TAB.filter(x=>allowedTab(x[0]));if(!allowedTab(store.adminTab))store.adminTab=tabs[0]?.[0]||'';modal('⚙️ لوحة إدارة متجر الجوكر',`<div class="staffHeader"><div><strong>${esc(authInfo())}</strong><span class="mute textsm">${isOwner()?'مدير — كل الصلاحيات':'موظف — تظهر فقط الوظائف المسموحة'}</span></div><button class="outline smallBtn" id="logout">تسجيل الخروج</button></div><div class="tabs" id="adminTabs">${tabs.map(([id,title])=>`<button data-tab="${id}" class="${store.adminTab===id?'active':''}">${title}</button>`).join('')}</div><div id="adminContent">جارٍ التحميل...</div>`,true);$('logout').onclick=async()=>{await db.auth.signOut();store.actor=null;stopNotify();closeModal();toast('تم تسجيل الخروج')};$('adminTabs').querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{store.adminTab=b.dataset.tab;$('adminTabs').querySelectorAll('[data-tab]').forEach(x=>x.classList.toggle('active',x.dataset.tab===store.adminTab));renderAdmin()});renderAdmin()}
