function offerForm(o=null){if(!requires('offers.manage'))return;const start=o?.start_at||new Date(now()).toISOString(),end=o?.end_at||new Date(now()+3*86400000).toISOString();modal(o?'تعديل عرض مميز':'إنشاء عرض مميز',`<form id="offerForm"><label class="field"><span>اختر القسم</span><select id="offerCategory">${store.categories.map(c=>`<option value="${esc(c.id)}">${esc(c.name)}</option>`).join('')}</select></label><label class="field"><span>اختر المنتج</span><select id="offerProduct" name="product" required></select></label><p class="mute" id="basePrice"></p><label class="field"><span>السعر المخفض (د.ل)</span><input name="price" type="number" min="0.01" step=".01" value="${esc(o?.offer_price??'')}" required></label><label class="field"><span>يبدأ في</span><input name="start" type="datetime-local" value="${localDate(start)}" required></label><label class="field"><span>ينتهي في</span><input name="end" type="datetime-local" value="${localDate(end)}" required></label><button class="gold">حفظ العرض</button><p id="offerError" class="order-error"></p></form>`);const oldProd=store.products.find(p=>String(p.id)===String(o?.product_id));if(oldProd)$('offerCategory').value=oldProd.category_id;const updateProduct=()=>{const id=$('offerCategory').value,arr=store.products.filter(p=>String(p.category_id)===id);$('offerProduct').innerHTML=arr.map(p=>`<option value="${esc(p.id)}">${esc(p.name)}</option>`).join('');if(oldProd&&arr.some(p=>p.id===oldProd.id))$('offerProduct').value=oldProd.id;updatePrice()};const updatePrice=()=>{const p=store.products.find(x=>String(x.id)===$('offerProduct').value);$('basePrice').textContent=p?'السعر الأساسي: '+fmt(p.price):'لا يوجد منتج في هذا القسم'};$('offerCategory').onchange=updateProduct;$('offerProduct').onchange=updatePrice;updateProduct();$('offerForm').onsubmit=async e=>{e.preventDefault();const btn=e.target.querySelector('button');btn.disabled=true;try{const f=new FormData(e.target),p=store.products.find(x=>String(x.id)===String(f.get('product'))),price=Number(f.get('price')),from=new Date(String(f.get('start'))),to=new Date(String(f.get('end')));if(!p||!Number.isFinite(price)||price<=0||price>=pnum(p.price))throw Error('سعر العرض يجب أن يكون أقل من السعر الأصلي');if(!Number.isFinite(from.getTime())||!Number.isFinite(to.getTime())||from>=to)throw Error('حدد تاريخ بداية ونهاية صحيحين');const payload={product_id:String(p.id),offer_price:price,start_at:from.toISOString(),end_at:to.toISOString()};const r=o?await db.from('joker_offers').update(payload).eq('id',o.id):await db.from('joker_offers').insert(payload);if(r.error)throw r.error;await loadStore();store.adminTab='offers';adminPanel();toast('تم حفظ العرض، ويبدأ وينتهي تلقائيًا')}catch(err){$('offerError').textContent=err.message;btn.disabled=false}}}
